import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Javascript","description":"Javascript reference documentation","frontmatter":{"title":"Javascript","description":"Javascript reference documentation"},"headers":[],"relativePath":"knowledge/javascript.md","filePath":"knowledge/javascript.md","lastUpdated":1784485118000}'),s={name:"knowledge/javascript.md"};function n(c,e,i,d,l,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="javascript" tabindex="-1">Javascript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;Javascript&quot;">​</a></h1><h1 id="javascript-es2017-—-knowledge-reference" tabindex="-1">JavaScript ES2017+ — Knowledge Reference <a class="header-anchor" href="#javascript-es2017-—-knowledge-reference" aria-label="Permalink to &quot;JavaScript ES2017+ — Knowledge Reference&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Reference for modern JavaScript (ES2017+) features essential for production development. Covers async patterns, closures, prototypes, event loop mechanics, modules, advanced data structures, and newer APIs like WeakRef and FinalizationRegistry.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="async-await" tabindex="-1">Async/Await <a class="header-anchor" href="#async-await" aria-label="Permalink to &quot;Async/Await&quot;">​</a></h3><p><code>async/await</code> is syntactic sugar over Promises. An <code>async</code> function always returns a Promise. <code>await</code> pauses execution until a Promise settles. Error handling uses <code>try/catch</code>. Async functions enable sequential-looking asynchronous code without callback nesting.</p><h3 id="promises" tabindex="-1">Promises <a class="header-anchor" href="#promises" aria-label="Permalink to &quot;Promises&quot;">​</a></h3><p>Promises represent eventual completion/failure of an asynchronous operation. Three states: pending, fulfilled, rejected. <code>Promise.all()</code> runs concurrently and rejects on first failure. <code>Promise.allSettled()</code> waits for all to settle regardless of outcome. <code>Promise.race()</code> returns first settled. <code>Promise.any()</code> returns first fulfilled, ignores rejections until all reject.</p><h3 id="closures" tabindex="-1">Closures <a class="header-anchor" href="#closures" aria-label="Permalink to &quot;Closures&quot;">​</a></h3><p>A closure is a function that retains access to its lexical scope even when executed outside that scope. Closures are fundamental to module patterns, callbacks, event handlers, and functional programming. Every function in JavaScript forms a closure over its surrounding variables.</p><h3 id="prototypes" tabindex="-1">Prototypes <a class="header-anchor" href="#prototypes" aria-label="Permalink to &quot;Prototypes&quot;">​</a></h3><p>JavaScript uses prototypal inheritance. Every object has an internal <code>[[Prototype]]</code> link. <code>Object.create()</code> sets the prototype. <code>class</code> syntax is syntactic sugar over prototype-based inheritance. <code>__proto__</code> is deprecated; use <code>Object.getPrototypeOf()</code> and <code>Object.setPrototypeOf()</code>.</p><h3 id="event-loop" tabindex="-1">Event Loop <a class="header-anchor" href="#event-loop" aria-label="Permalink to &quot;Event Loop&quot;">​</a></h3><p>JavaScript is single-threaded with an event loop. Call stack executes synchronous code. Microtasks (Promises, <code>queueMicrotask</code>) run after each task. Macrotasks (<code>setTimeout</code>, <code>setImmediate</code>, I/O callbacks) run between task batches. <code>process.nextTick()</code> (Node.js) runs before other microtasks.</p><h3 id="es-modules" tabindex="-1">ES Modules <a class="header-anchor" href="#es-modules" aria-label="Permalink to &quot;ES Modules&quot;">​</a></h3><p>ESM is the standard module system. <code>import</code>/<code>export</code> syntax. Static analysis enables tree-shaking. Modules are deferred by default. <code>import()</code> enables dynamic imports. Named exports vs default exports — prefer named exports for better refactoring and tree-shaking.</p><h3 id="iterators-and-generators" tabindex="-1">Iterators and Generators <a class="header-anchor" href="#iterators-and-generators" aria-label="Permalink to &quot;Iterators and Generators&quot;">​</a></h3><p>Iterator protocol: <code>next()</code> method returning <code>{ value, done }</code>. Generator functions (<code>function*</code>) yield values lazily. <code>for...of</code> consumes iterators. Generators enable custom iteration, lazy evaluation, and coroutine-like patterns.</p><h3 id="proxy-and-reflect" tabindex="-1">Proxy and Reflect <a class="header-anchor" href="#proxy-and-reflect" aria-label="Permalink to &quot;Proxy and Reflect&quot;">​</a></h3><p><code>Proxy</code> intercepts operations on objects (get, set, has, deleteProperty, apply, construct). <code>Reflect</code> provides default operations matching each Proxy trap. Used for validation, logging, reactive systems, and metaprogramming.</p><h3 id="weakref-and-finalizationregistry" tabindex="-1">WeakRef and FinalizationRegistry <a class="header-anchor" href="#weakref-and-finalizationregistry" aria-label="Permalink to &quot;WeakRef and FinalizationRegistry&quot;">​</a></h3><p><code>WeakRef</code> holds a weak reference to an object, allowing garbage collection. <code>FinalizationRegistry</code> registers callbacks for when objects are garbage collected. Used for caches, resource management, and memory-sensitive applications. Unreliable for timing-critical operations.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Use <code>async/await</code> over raw Promises</strong> — sequential async code is more readable; chain <code>.then()</code> only for independent parallel operations</li><li><strong>Always handle Promise rejections</strong> — unhandled rejections crash Node.js processes; use <code>try/catch</code> or <code>.catch()</code> on every Promise chain</li><li><strong>Prefer <code>const</code> over <code>let</code></strong> — immutability by default prevents accidental reassignment; use <code>let</code> only when reassignment is genuinely needed</li><li><strong>Use arrow functions for callbacks, regular functions for methods</strong> — arrow functions capture <code>this</code> lexically; regular functions have dynamic <code>this</code></li><li><strong>Use <code>Map</code>/<code>Set</code> over plain objects for collections</strong> — <code>Map</code> preserves key types, supports non-string keys, and has O(1) lookup; <code>Set</code> for unique values</li><li><strong>Leverage destructuring for clean parameter extraction</strong> — <code>function createUser({ name, email, role = &#39;user&#39; })</code> is cleaner than manual property access</li><li><strong>Use template literals over string concatenation</strong> — better readability, multi-line support, and tagged template literals for advanced use cases</li><li><strong>Prefer <code>for...of</code> over <code>for</code> loops for iteration</strong> — <code>for...of</code> is cleaner, works with iterables, and avoids off-by-one errors</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong><code>var</code> usage</strong> — function-scoped instead of block-scoped; causes hoisting bugs; always use <code>const</code>/<code>let</code></li><li><strong>Deep Promise chains without <code>await</code></strong> — nested <code>.then()</code> callbacks defeat the purpose of Promises; use <code>async/await</code></li><li><strong>Using <code>==</code> instead of <code>===</code></strong> — loose equality performs type coercion with unexpected results; always use strict equality</li><li><strong>Mutating function parameters</strong> — side effects make code unpredictable; treat parameters as immutable</li><li><strong>Creating new arrays/objects in hot loops</strong> — allocation pressure causes GC pauses; reuse or pre-allocate when performance matters</li><li><strong>Using <code>arguments</code> object</strong> — not available in arrow functions, array-like but not an array; use rest parameters (<code>...args</code>)</li><li><strong>Synchronous I/O in async contexts</strong> — blocking the event loop with <code>fs.readFileSync</code> degrades throughput; use async alternatives</li><li><strong>Not using optional chaining for deeply nested access</strong> — <code>a?.b?.c?.d</code> prevents TypeError; nullish coalescing (<code>??</code>) provides defaults</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Forgetting that <code>async</code> functions return Promises</strong> — <code>const result = await asyncFn()</code> is correct; <code>await</code> unwraps the Promise</li><li><strong><code>this</code> binding confusion in callbacks</strong> — arrow functions capture <code>this</code> from enclosing scope; regular functions get <code>this</code> from call site</li><li><strong>Stale closure in <code>useEffect</code></strong> — the closure captures variables at creation time; use dependency arrays or functional updates</li><li><strong>Not understanding Promise microtask timing</strong> — <code>Promise.resolve().then(fn)</code> runs before <code>setTimeout(fn, 0)</code></li><li><strong>Overwriting <code>Array.prototype</code> or <code>Object.prototype</code></strong> — prototype pollution breaks all code sharing the same prototype chain</li><li><strong>Using <code>Array.includes</code> for objects</strong> — <code>includes</code> checks reference equality, not structural equality; use <code>.find()</code> with a predicate</li><li><strong>Ignoring <code>Symbol</code> for unique identifiers</strong> — <code>Symbol()</code> creates truly unique values; useful for private properties and well-known symbols</li><li><strong>Not using <code>finally</code> for cleanup</strong> — <code>try/catch/finally</code> ensures cleanup runs regardless of success or failure</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Approach</th></tr></thead><tbody><tr><td>Sequential async operations</td><td><code>async/await</code></td></tr><tr><td>Independent parallel async</td><td><code>Promise.all()</code> / <code>Promise.allSettled()</code></td></tr><tr><td>First settled wins</td><td><code>Promise.race()</code></td></tr><tr><td>First fulfilled wins</td><td><code>Promise.any()</code></td></tr><tr><td>Key-value collection</td><td><code>Map</code></td></tr><tr><td>Unique values</td><td><code>Set</code></td></tr><tr><td>Weak references for caches</td><td><code>WeakMap</code> / <code>WeakRef</code></td></tr><tr><td>Lazy iteration</td><td>Generator function</td></tr><tr><td>Metaprogramming</td><td><code>Proxy</code> + <code>Reflect</code></td></tr><tr><td>Dynamic imports</td><td><code>import()</code></td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript" target="_blank" rel="noreferrer">MDN JavaScript Reference</a></li><li><a href="https://javascript.info" target="_blank" rel="noreferrer">JavaScript.info</a></li><li><a href="https://tc39.es/ecma262" target="_blank" rel="noreferrer">ECMAScript Specification</a></li><li><a href="https://nodejs.org/api" target="_blank" rel="noreferrer">Node.js API Documentation</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><code>WeakRef</code> and <code>FinalizationRegistry</code> are not widely used in application code; they&#39;re for library authors and memory-sensitive systems</li><li><code>Promise.allSettled()</code> was introduced in ES2020; polyfill for older environments</li><li><code>structuredClone()</code> (ES2022) performs deep cloning including circular references; replaces manual JSON parse/stringify cloning</li><li><code>Array.at()</code> (ES2022) enables negative indexing: <code>arr.at(-1)</code> returns the last element</li><li><code>Object.hasOwn()</code> (ES2022) replaces <code>obj.hasOwnProperty()</code> which can be overridden</li><li><code>using</code> keyword (ES2022/explicit resource management) is experimental; check runtime support before adopting</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',37)])])}const f=o(s,[["render",n]]);export{h as __pageData,f as default};
